// A member-encrypted RAR5 store archive generated by RARLAB rar 7.20 for the
// rarpar test corpus, password `testpass123`, holding `small.txt`.
const ENCRYPTED: &[u8] = include_bytes!(
    "../../../../server/crates/weaver-server-core/tests/fixtures/rar5/rar5_enc_store.rar"
);
const ENCRYPTED_MEMBER: &[u8] = include_bytes!(
    "../../../../server/crates/weaver-server-core/tests/fixtures/originals/small.txt"
);
// A member-encrypted RAR4 archive compressed with LZ, password `testpass123`,
// holding `compressible.txt`: a RAR4 key has no check of its own, so a wrong
// one shows only in what the decoder makes of the bytes.
const ENCRYPTED_LZ: &[u8] = include_bytes!(
    "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar4_enc_lz.rar"
);
const ENCRYPTED_LZ_MEMBER_LEN: u64 = 226_943;

// RAR5 store volumes, written here the way the format lays them out.
mod rar5 {
    use super::crc32;

    pub const SPLIT_BEFORE: u64 = 0x0008;
    pub const SPLIT_AFTER: u64 = 0x0010;

    fn vint(mut value: u64) -> Vec<u8> {
        let mut out = Vec::new();
        loop {
            let byte = (value & 0x7f) as u8;
            value >>= 7;
            if value == 0 {
                out.push(byte);
                return out;
            }
            out.push(byte | 0x80);
        }
    }

    fn header(kind: u64, flags: u64, data: Option<u64>, body: &[u8]) -> Vec<u8> {
        let mut inner = vint(kind);
        inner.extend(vint(flags | if data.is_some() { 0x0002 } else { 0 }));
        if let Some(data) = data {
            inner.extend(vint(data));
        }
        inner.extend_from_slice(body);
        let size = vint(inner.len() as u64);
        let crc = crc32(&[size.as_slice(), inner.as_slice()].concat());
        [crc.to_le_bytes().as_slice(), &size, &inner].concat()
    }

    // The signature and main header; `volume` is `None` for a lone archive.
    pub fn start(volume: Option<u64>) -> Vec<u8> {
        let body = match volume {
            None => vint(0),
            Some(0) => vint(0x0001),
            Some(number) => [vint(0x0003), vint(number)].concat(),
        };
        [
            b"Rar!\x1a\x07\x01\x00".as_slice(),
            &header(1, 0, None, &body),
        ]
        .concat()
    }

    // The signature and a main header with the archive flags given, solid
    // among them, for volume `number` of a set.
    pub fn start_flagged(flags: u64, number: u64) -> Vec<u8> {
        let body = match number {
            0 => vint(flags | 0x0001),
            number => [vint(flags | 0x0003), vint(number)].concat(),
        };
        [
            b"Rar!\x1a\x07\x01\x00".as_slice(),
            &header(1, 0, None, &body),
        ]
        .concat()
    }

    pub const SOLID: u64 = 0x0004;

    pub fn end(more: bool) -> Vec<u8> {
        header(5, 0, None, &vint(u64::from(more)))
    }

    // A stored member's header and its data.
    pub fn file(name: &str, split: u64, data: &[u8], length: u64, crc: Option<u32>) -> Vec<u8> {
        file_as(name, split, data, length, crc, 0)
    }

    // A member's header naming `compression` as its compression info, and
    // its data as given.
    pub fn file_as(
        name: &str,
        split: u64,
        data: &[u8],
        length: u64,
        crc: Option<u32>,
        compression: u64,
    ) -> Vec<u8> {
        let mut body = vint(if crc.is_some() { 0x0004 } else { 0 });
        body.extend(vint(length));
        body.extend(vint(0o644));
        if let Some(crc) = crc {
            body.extend(crc.to_le_bytes());
        }
        body.extend(vint(compression));
        body.extend(vint(1));
        body.extend(vint(name.len() as u64));
        body.extend_from_slice(name.as_bytes());
        [
            header(2, split, Some(data.len() as u64), &body),
            data.to_vec(),
        ]
        .concat()
    }

    // A directory's header: the directory flag, and no data.
    pub fn directory(name: &str) -> Vec<u8> {
        let mut body = vint(0x0001);
        body.extend(vint(0));
        body.extend(vint(0o755));
        body.extend(vint(0));
        body.extend(vint(1));
        body.extend(vint(name.len() as u64));
        body.extend_from_slice(name.as_bytes());
        header(2, 0, None, &body)
    }
}

const NOTES: &[u8] = b"the first member, stored";

fn second() -> Vec<u8> {
    (0..64u8).collect()
}

fn spanning() -> Vec<u8> {
    (0..40u8).map(|byte| byte.wrapping_mul(7)).collect()
}

fn one_volume() -> Vec<u8> {
    let second = second();
    [
        rar5::start(None),
        rar5::file(
            "notes.txt",
            0,
            NOTES,
            NOTES.len() as u64,
            Some(crc32(NOTES)),
        ),
        rar5::file(
            "deep/second.bin",
            0,
            &second,
            second.len() as u64,
            Some(crc32(&second)),
        ),
        rar5::end(false),
    ]
    .concat()
}

fn two_volumes() -> Vec<Vec<u8>> {
    let spanning = spanning();
    let length = spanning.len() as u64;
    let (front, back) = spanning.split_at(16);
    vec![
        [
            rar5::start(Some(0)),
            rar5::file("spanning.bin", rar5::SPLIT_AFTER, front, length, None),
            rar5::end(true),
        ]
        .concat(),
        [
            rar5::start(Some(1)),
            rar5::file(
                "spanning.bin",
                rar5::SPLIT_BEFORE,
                back,
                length,
                Some(crc32(&spanning)),
            ),
            rar5::file("tail.txt", 0, NOTES, NOTES.len() as u64, Some(crc32(NOTES))),
            rar5::end(false),
        ]
        .concat(),
    ]
}

// Volumes in memory whose bytes the test hands out. A read past what was
// handed out waits, and says which volume it waits on, so a test can act
// once the run is truly blocked.
struct Gate {
    volumes: Vec<Vec<u8>>,
    state: Mutex<State>,
    changed: Condvar,
}

struct State {
    released: Vec<bool>,
    waiting: Option<u32>,
}

impl Gate {
    fn new(volumes: Vec<Vec<u8>>, released: &[bool]) -> Arc<Self> {
        Arc::new(Self {
            volumes,
            state: Mutex::new(State {
                released: released.to_vec(),
                waiting: None,
            }),
            changed: Condvar::new(),
        })
    }

    fn whole(volumes: Vec<Vec<u8>>) -> Arc<Self> {
        let released = vec![true; volumes.len()];
        Self::new(volumes, &released)
    }

    fn release(&self, volume: u32) {
        let mut state = self.state.lock().unwrap();
        state.released[volume as usize] = true;
        self.changed.notify_all();
    }

    fn wait_for_reader(&self, volume: u32) {
        let mut state = self.state.lock().unwrap();
        while state.waiting != Some(volume) {
            state = self.changed.wait(state).unwrap();
        }
    }
}

impl Volumes for Gate {
    fn next(&self, after: Option<VolumeIndex>) -> std::io::Result<Option<VolumeIndex>> {
        let next = after.map_or(0, |after| after.0 as usize + 1);
        Ok((next < self.volumes.len()).then_some(VolumeIndex(next as u32)))
    }

    fn len(&self, volume: VolumeIndex) -> Option<u64> {
        let state = self.state.lock().unwrap();
        let at = volume.0 as usize;
        state
            .released
            .get(at)
            .is_some_and(|released| *released)
            .then(|| self.volumes[at].len() as u64)
    }

    // A released volume's bytes are all in.
    fn settled(&self, volume: VolumeIndex) -> bool {
        self.len(volume).is_some()
    }

    fn read_at(&self, volume: VolumeIndex, offset: u64, into: &mut [u8]) -> io::Result<usize> {
        let bytes = self
            .volumes
            .get(volume.0 as usize)
            .ok_or_else(|| io::Error::from(io::ErrorKind::NotFound))?;
        let mut state = self.state.lock().unwrap();
        while !state.released[volume.0 as usize] {
            state.waiting = Some(volume.0);
            self.changed.notify_all();
            state = self.changed.wait(state).unwrap();
        }
        let start = (offset as usize).min(bytes.len());
        let read = into.len().min(bytes.len() - start);
        into[..read].copy_from_slice(&bytes[start..start + read]);
        Ok(read)
    }
}

// What a run said, with each member's bytes joined in order.
#[derive(Debug, PartialEq, Eq)]
enum Said {
    Member(u32, String, Option<u64>),
    Bytes(u32, Vec<u8>),
    Closed(u32),
    Retract(u32),
    NeedsPassword,
    Refuse(Why),
    Damaged(u32, u64, u64),
}

fn said(emits: &[Emit]) -> Vec<Said> {
    let mut out: Vec<Said> = Vec::new();
    for emit in emits {
        match emit {
            Emit::Member {
                member,
                name,
                length,
            } => out.push(Said::Member(member.0, name.clone(), *length)),
            Emit::Bytes {
                member,
                offset,
                bytes,
                provenance,
            } => {
                assert_eq!(*provenance, weaver_graph::Provenance::Fresh);
                match out.last_mut() {
                    Some(Said::Bytes(last, joined)) if *last == member.0 => {
                        assert_eq!(*offset, joined.len() as u64);
                        joined.extend_from_slice(bytes);
                    }
                    _ => {
                        assert_eq!(*offset, 0);
                        out.push(Said::Bytes(member.0, bytes.to_vec()));
                    }
                }
            }
            Emit::MemberClosed(member) => out.push(Said::Closed(member.0)),
            Emit::Retract(member) => out.push(Said::Retract(member.0)),
            Emit::NeedsPassword => out.push(Said::NeedsPassword),
            Emit::Refuse(why) => out.push(Said::Refuse(*why)),
            Emit::Damaged { volume, range } => {
                out.push(Said::Damaged(volume.0, range.start, range.end))
            }
            // Said beside the walk; `checksums` reads them.
            Emit::Checksum { .. } => {}
            other => panic!("an engine run does not say {other:?}"),
        }
    }
    out
}

fn run(engine: &mut RarEngine, volumes: Vec<Vec<u8>>) -> Vec<Said> {
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    engine.start().run(
        Gate::whole(volumes),
        &mut sink,
        weaver_graph::Budget::default(),
    );
    said(&emits)
}

fn named(names: &[&str]) -> RarEngine {
    let mut engine = RarEngine::new();
    for (volume, name) in names.iter().enumerate() {
        engine.bound(VolumeIndex(volume as u32), name, &[], None);
    }
    engine
}

#[test]
fn a_store_archive_extracts_its_members_by_name_and_closes_them() {
    let said = run(&mut RarEngine::new(), vec![one_volume()]);
    assert_eq!(
        said,
        vec![
            Said::Member(0, "notes.txt".into(), Some(NOTES.len() as u64)),
            Said::Bytes(0, NOTES.to_vec()),
            Said::Closed(0),
            Said::Member(1, "deep/second.bin".into(), Some(64)),
            Said::Bytes(1, second()),
            Said::Closed(1),
        ]
    );
}

#[test]
fn a_directory_is_a_member_with_nothing_in_it_named_with_a_trailing_slash() {
    let archive = [
        rar5::start(None),
        rar5::directory("hollow"),
        rar5::file(
            "notes.txt",
            0,
            NOTES,
            NOTES.len() as u64,
            Some(crc32(NOTES)),
        ),
        rar5::end(false),
    ]
    .concat();
    assert_eq!(
        run(&mut RarEngine::new(), vec![archive]),
        vec![
            Said::Member(0, "hollow/".into(), Some(0)),
            Said::Closed(0),
            Said::Member(1, "notes.txt".into(), Some(NOTES.len() as u64)),
            Said::Bytes(1, NOTES.to_vec()),
            Said::Closed(1),
        ]
    );
}

#[test]
fn a_member_spanning_two_volumes_extracts_whole() {
    let said = run(
        &mut named(&["set.part1.rar", "set.part2.rar"]),
        two_volumes(),
    );
    assert_eq!(
        said,
        vec![
            Said::Member(0, "spanning.bin".into(), Some(40)),
            Said::Bytes(0, spanning()),
            Said::Closed(0),
            Said::Member(1, "tail.txt".into(), Some(NOTES.len() as u64)),
            Said::Bytes(1, NOTES.to_vec()),
            Said::Closed(1),
        ]
    );
}

#[test]
fn claim_names_the_volumes_of_its_own_set_only() {
    let mut engine = named(&["Set.part1.rar"]);
    assert_eq!(
        engine.claim("set.PART2.rar", b"", None),
        vec![VolumeIndex(1)]
    );
    assert_eq!(
        engine.claim("set.part10.rar", b"", None),
        vec![VolumeIndex(9)]
    );
    assert_eq!(
        engine.claim("set.part01.rar", b"", None),
        vec![VolumeIndex(0)],
        "a volume posted again is that volume"
    );
    assert_eq!(
        engine.claim("other.part2.rar", b"", None),
        Vec::<VolumeIndex>::new()
    );
    assert_eq!(
        engine.claim("set.r00", b"", None),
        Vec::<VolumeIndex>::new()
    );
    assert_eq!(
        engine.claim("set.par2", b"", None),
        Vec::<VolumeIndex>::new()
    );

    let mut old = named(&["set.rar"]);
    assert_eq!(old.claim("set.r00", b"", None), vec![VolumeIndex(1)]);
    assert_eq!(old.claim("SET.R41", b"", None), vec![VolumeIndex(42)]);
    // `.sNN` follows `.r99`.
    assert_eq!(old.claim("set.s00", b"", None), vec![VolumeIndex(101)]);
    assert_eq!(
        old.claim("set.part2.rar", b"", None),
        Vec::<VolumeIndex>::new()
    );
    assert_eq!(old.claim("set.rar", b"", None), vec![VolumeIndex(0)]);
}

#[test]
fn number_alone_does_not_join_different_named_rar_sets() {
    let held = [
        rar5::start(Some(2)),
        rar5::file(
            "first.bin",
            rar5::SPLIT_BEFORE | rar5::SPLIT_AFTER,
            b"held",
            12,
            None,
        ),
        rar5::end(true),
    ]
    .concat();
    let candidate = [
        rar5::start(Some(0)),
        rar5::file("second.bin", rar5::SPLIT_AFTER, b"next", 12, None),
        rar5::end(true),
    ]
    .concat();
    let mut store = crate::rar_store::RarStore::new();
    store.bound(
        VolumeIndex(2),
        "first.part03.rar",
        &held,
        Some(held.len() as u64),
    );
    assert_eq!(
        store.claim(
            "second.part01.rar",
            &candidate,
            Some(candidate.len() as u64)
        ),
        Vec::<VolumeIndex>::new(),
        "the streaming store uses the same membership boundary"
    );
    let mut engine = RarEngine::new();
    engine.bound(
        VolumeIndex(2),
        "first.part03.rar",
        &held,
        Some(held.len() as u64),
    );
    assert_eq!(
        engine.claim("first.part01.rar", &candidate, Some(candidate.len() as u64)),
        vec![VolumeIndex(0)],
        "a matching set name places an earlier volume"
    );
    assert_eq!(
        engine.claim(
            "second.part01.rar",
            &candidate,
            Some(candidate.len() as u64)
        ),
        Vec::<VolumeIndex>::new(),
        "an unjudged number cannot join another named set"
    );
}

#[test]
fn linked_headers_can_join_different_posted_rar_names() {
    let volumes = two_volumes();
    let mut engine = RarEngine::new();
    engine.bound(VolumeIndex(1), "first.part02.rar", &volumes[1], None);
    assert_eq!(
        engine.claim("second.part01.rar", &volumes[0], None),
        vec![VolumeIndex(0)],
        "the held continuation judges membership across posted labels"
    );
}

// Names that number nothing of a RAR set: each volume is placed by what its
// headers state beside the fronts of the volumes bound, as the store that
// gave the set up placed them.
#[test]
fn claim_places_a_nameless_volume_by_its_headers() {
    let volumes = two_volumes();
    let mut engine = RarEngine::new();
    engine.bound(VolumeIndex(0), "a1b2.101", &volumes[0], None);
    assert_eq!(
        engine.claim("a1b2.102", &volumes[1], None),
        vec![VolumeIndex(1)]
    );
    assert_eq!(
        engine.claim("a1b2.103", &volumes[0], None),
        vec![VolumeIndex(0)],
        "a volume posted again is that volume"
    );
    assert_eq!(
        engine.claim("a1b2.103", &one_volume(), None),
        Vec::<VolumeIndex>::new(),
        "no volume of a set"
    );
    assert_eq!(
        engine.claim("a1b2.103", b"", None),
        Vec::<VolumeIndex>::new(),
        "a front that says nothing"
    );
    let stranger = [
        rar5::start(Some(1)),
        rar5::file("other.bin", rar5::SPLIT_BEFORE, NOTES, 99, None),
    ]
    .concat();
    assert_eq!(
        engine.claim("a1b2.103", &stranger, None),
        Vec::<VolumeIndex>::new(),
        "it continues no member of ours"
    );

    engine.bound(VolumeIndex(1), "a1b2.102", &volumes[1], None);
    let said = run(&mut engine, volumes);
    assert_eq!(said[1], Said::Bytes(0, spanning()));
}

// A store gives the engine a volume whose front never reached the tree, as
// after a restart: bound, it states nothing. The next volume states its
// number, and the one before it, saying nothing, says nothing against it.
#[test]
fn a_stated_volume_is_placed_beside_a_bound_volume_whose_front_is_unread() {
    let volumes = two_volumes();
    let mut engine = RarEngine::new();
    engine.bound(VolumeIndex(0), "a1b2.101", &volumes[0], None);
    engine.bound(VolumeIndex(1), "a1b2.102", b"", None);
    let third = [
        rar5::start(Some(2)),
        rar5::file("tail.bin", 0, NOTES, NOTES.len() as u64, Some(crc32(NOTES))),
        rar5::end(false),
    ]
    .concat();
    assert_eq!(engine.claim("a1b2.103", &third, None), vec![VolumeIndex(2)]);
}

#[test]
fn the_engine_bids_for_the_volumes_after_the_one_the_run_reached() {
    let mut engine = named(&["set.part1.rar", "set.part2.rar", "set.part3.rar"]);
    let mut seeks = Vec::new();
    engine.wants(&mut seeks);
    assert!(
        seeks.is_empty(),
        "nothing is bid but where the owner says the run is"
    );

    engine.bid(VolumeIndex(0), &mut seeks);
    let bids: Vec<_> = seeks
        .iter()
        .map(|seek| (seek.volume.0, seek.weight.0, seek.purpose))
        .collect();
    assert_eq!(bids, vec![(1, 1, Purpose::Data), (2, 2, Purpose::Data)]);

    seeks.clear();
    engine.bound(VolumeIndex(3), "set.part4.rar", &[], None);
    engine.bid(VolumeIndex(1), &mut seeks);
    let bids: Vec<_> = seeks
        .iter()
        .map(|seek| (seek.volume.0, seek.weight.0))
        .collect();
    assert_eq!(
        bids,
        vec![(2, 1), (3, 2)],
        "the bids are restated from where the run stands"
    );
}

#[test]
fn the_object_is_an_engine_that_reads_in_order_and_keeps_nothing() {
    let object = crate::build(
        Kind::RarEngine,
        ObjectId(4),
        weaver_graph::Budget::default(),
    )
    .unwrap();
    assert_eq!(object.kind(), Kind::RarEngine);
    assert!(object.reads_in_order());
    assert!(object.engine().is_some());
    let mut placed = Vec::new();
    object.locate(VolumeIndex(2), ByteRange::new(5, 9), &mut placed);
    assert_eq!(
        placed,
        vec![Placement::Envelope {
            envelope: 2,
            range: ByteRange::new(5, 9)
        }]
    );
    assert_eq!(object.envelope(2, ByteRange::new(5, 9)), None);
}

#[test]
fn a_run_waits_for_bytes_not_yet_there_and_continues_when_they_land() {
    let gate = Gate::new(two_volumes(), &[true, false]);
    let (sent, heard) = mpsc::channel();
    let extraction = named(&["set.part1.rar", "set.part2.rar"]).start();
    let volumes: Arc<dyn Volumes> = gate.clone();
    let runner = thread::spawn(move || {
        let mut sink = |emit| sent.send(emit).is_ok();
        extraction.run(volumes, &mut sink, weaver_graph::Budget::default());
    });

    let mut emits = vec![heard.recv().unwrap()];
    gate.wait_for_reader(1);
    emits.extend(heard.try_iter());
    let so_far = said(&emits);
    assert_eq!(so_far[0], Said::Member(0, "spanning.bin".into(), Some(40)));
    assert!(
        !so_far.contains(&Said::Closed(0)),
        "the member cannot close before its second volume lands"
    );

    gate.release(1);
    runner.join().unwrap();
    emits.extend(heard.try_iter());
    assert_eq!(
        said(&emits),
        vec![
            Said::Member(0, "spanning.bin".into(), Some(40)),
            Said::Bytes(0, spanning()),
            Said::Closed(0),
            Said::Member(1, "tail.txt".into(), Some(NOTES.len() as u64)),
            Said::Bytes(1, NOTES.to_vec()),
            Said::Closed(1),
        ]
    );
}

#[test]
fn a_wrong_password_asks_for_another_and_the_right_one_extracts() {
    let mut engine = named(&["locked.rar"]);
    assert_eq!(
        run(&mut engine, vec![ENCRYPTED.to_vec()]),
        vec![Said::NeedsPassword],
        "an encrypted member with no password is never announced"
    );

    let mut out = Vec::new();
    engine.offer_password("not-the-password", &mut out);
    let wrong = run(&mut engine, vec![ENCRYPTED.to_vec()]);
    assert_eq!(wrong.last(), Some(&Said::NeedsPassword));
    assert!(!wrong.iter().any(|said| matches!(said, Said::Closed(_))));

    engine.offer_password("testpass123", &mut out);
    assert!(out.is_empty());
    assert_eq!(
        run(&mut engine, vec![ENCRYPTED.to_vec()]),
        vec![
            Said::Member(0, "small.txt".into(), Some(ENCRYPTED_MEMBER.len() as u64)),
            Said::Bytes(0, ENCRYPTED_MEMBER.to_vec()),
            Said::Closed(0),
        ]
    );
}

// A wrong RAR4 key fails the decoder before any checksum: on bytes as they
// were posted, that asks for another password and says no damage.
#[test]
fn a_wrong_rar4_key_the_decoder_rejects_asks_for_another_and_the_right_one_extracts() {
    let mut engine = named(&["rar4_enc_lz.rar"]);
    let mut out = Vec::new();
    engine.offer_password("not-the-password", &mut out);
    let wrong = run(&mut engine, vec![ENCRYPTED_LZ.to_vec()]);
    assert_eq!(wrong.last(), Some(&Said::NeedsPassword));
    assert!(
        !wrong
            .iter()
            .any(|said| { matches!(said, Said::Closed(_) | Said::Damaged(..) | Said::Refuse(_)) })
    );

    engine.offer_password("testpass123", &mut out);
    assert!(out.is_empty());
    let right = run(&mut engine, vec![ENCRYPTED_LZ.to_vec()]);
    assert_eq!(
        right[0],
        Said::Member(0, "compressible.txt".into(), Some(ENCRYPTED_LZ_MEMBER_LEN))
    );
    assert!(matches!(
        &right[1],
        Said::Bytes(0, bytes) if bytes.len() as u64 == ENCRYPTED_LZ_MEMBER_LEN
    ));
    assert_eq!(right[2], Said::Closed(0));
}

#[test]
fn a_member_whose_checksum_fails_is_retracted_and_its_volume_damaged() {
    let mut volume = one_volume();
    let at = volume
        .windows(NOTES.len())
        .position(|window| window == NOTES)
        .unwrap();
    volume[at + 3] ^= 0x20;
    let length = volume.len() as u64;
    let said = run(&mut RarEngine::new(), vec![volume]);
    // A checksum failure is damage a repair can mend, not a refusal.
    assert_eq!(
        said[said.len() - 2..],
        [Said::Retract(0), Said::Damaged(0, 0, length)]
    );
    assert!(!said.contains(&Said::Closed(0)));
}

// A volume still growing has no length, so a checksum failure on it can say
// damage only over what the run read of it, and says exactly that.
#[test]
fn a_checksum_failure_on_a_growing_volume_damages_the_bytes_the_run_read() {
    struct Growing {
        bytes: Vec<u8>,
        reached: AtomicU64,
    }
    impl Volumes for Growing {
        fn next(&self, after: Option<VolumeIndex>) -> io::Result<Option<VolumeIndex>> {
            Ok(after.is_none().then_some(VolumeIndex(0)))
        }
        fn len(&self, _: VolumeIndex) -> Option<u64> {
            None
        }
        fn read_at(&self, _: VolumeIndex, offset: u64, into: &mut [u8]) -> io::Result<usize> {
            let start = (offset as usize).min(self.bytes.len());
            let read = into.len().min(self.bytes.len() - start);
            into[..read].copy_from_slice(&self.bytes[start..start + read]);
            self.reached
                .fetch_max(offset + read as u64, std::sync::atomic::Ordering::Relaxed);
            Ok(read)
        }
    }
    let mut bytes = one_volume();
    let at = bytes
        .windows(NOTES.len())
        .position(|window| window == NOTES)
        .unwrap();
    bytes[at + 3] ^= 0x20;
    let growing = Arc::new(Growing {
        bytes,
        reached: AtomicU64::new(0),
    });
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    RarEngine::new().start().run(
        Arc::clone(&growing) as Arc<dyn Volumes>,
        &mut sink,
        weaver_graph::Budget::default(),
    );
    let read = growing.reached.load(std::sync::atomic::Ordering::Relaxed);
    assert!(read > at as u64, "the run read past the failing bytes");
    let said = said(&emits);
    assert_eq!(
        said[said.len() - 2..],
        [Said::Retract(0), Said::Damaged(0, 0, read)]
    );
}

#[test]
fn a_sink_that_says_stop_hears_nothing_more() {
    let mut emits = Vec::new();
    let mut sink = |emit: Emit| {
        let stop = matches!(emit, Emit::Bytes { .. });
        emits.push(emit);
        !stop
    };
    RarEngine::new().start().run(
        Gate::whole(vec![one_volume()]),
        &mut sink,
        weaver_graph::Budget::default(),
    );
    let said = said(&emits);
    assert_eq!(said.len(), 2);
    assert_eq!(
        said[0],
        Said::Member(0, "notes.txt".into(), Some(NOTES.len() as u64))
    );
    assert!(matches!(said[1], Said::Bytes(0, _)));
}

// Each member's checksum as the run said it, in the order it was said.
fn checksums(emits: &[Emit]) -> Vec<(u32, u32)> {
    emits
        .iter()
        .filter_map(|emit| match emit {
            Emit::Checksum { member, crc32 } => Some((member.0, *crc32)),
            _ => None,
        })
        .collect()
}

// A compressed RAR4 member split across four volumes generated by RARLAB rar
// for the rarpar test corpus: each part's header carries its own part's CRC,
// and only the last part's is the member's.
const SPLIT_LZ: [&[u8]; 4] = [
    include_bytes!(
        "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar4_lz_four.part01.rar"
    ),
    include_bytes!(
        "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar4_lz_four.part02.rar"
    ),
    include_bytes!(
        "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar4_lz_four.part03.rar"
    ),
    include_bytes!(
        "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar4_lz_four.part04.rar"
    ),
];
const SPLIT_LZ_MEMBER_LEN: u64 = 226_943;
const SPLIT_LZ_MEMBER_CRC: u32 = 0x06b1_9020;

// A run over `volumes` of the four-part set, everything it said.
fn split_lz(volumes: &[&[u8]]) -> Vec<Emit> {
    let mut engine = named(&[
        "rar4_lz_four.part01.rar",
        "rar4_lz_four.part02.rar",
        "rar4_lz_four.part03.rar",
        "rar4_lz_four.part04.rar",
    ]);
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    engine.start().run(
        Gate::whole(volumes.iter().map(|volume| volume.to_vec()).collect()),
        &mut sink,
        weaver_graph::Budget::default(),
    );
    emits
}

// A split compressed member states the checksum its final part's header
// gives, once decoding has read that header: after its last bytes, before
// it closes, and equal to the CRC32 of the bytes it delivered. The first
// part's header carries only that part's packed-bytes CRC, which names
// nothing about the member and is never said.
#[test]
fn a_split_compressed_member_states_its_own_checksum_once_decoded() {
    let emits = split_lz(&SPLIT_LZ);
    let said = said(&emits);
    let bytes: Vec<u8> = said
        .iter()
        .filter_map(|said| match said {
            Said::Bytes(0, bytes) => Some(bytes.as_slice()),
            _ => None,
        })
        .flatten()
        .copied()
        .collect();
    assert_eq!(bytes.len() as u64, SPLIT_LZ_MEMBER_LEN);
    assert_eq!(crc32(&bytes), SPLIT_LZ_MEMBER_CRC);
    assert_eq!(checksums(&emits), vec![(0, crc32(&bytes))]);
    let at = |wanted: fn(&Emit) -> bool| emits.iter().rposition(wanted).unwrap();
    let stated = at(|emit| matches!(emit, Emit::Checksum { .. }));
    assert!(at(|emit| matches!(emit, Emit::Bytes { .. })) < stated);
    assert_eq!(stated + 1, at(|emit| matches!(emit, Emit::MemberClosed(_))));
}

// A member whose final part never arrives is never decoded whole, so the
// header that states its checksum is never read and none is said.
#[test]
fn a_split_member_whose_final_part_is_never_read_states_no_checksum() {
    let emits = split_lz(&SPLIT_LZ[..3]);
    assert_eq!(checksums(&emits), Vec::new());
    assert!(!said(&emits).contains(&Said::Closed(0)));
}

// An encrypted RAR5 member's header states a keyed CRC32, which is not the
// member's own, so the run says none for it.
#[test]
fn an_encrypted_rar5_member_states_no_keyed_checksum() {
    let mut engine = named(&["locked.rar"]);
    let mut out = Vec::new();
    engine.offer_password("testpass123", &mut out);
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    engine.start().run(
        Gate::whole(vec![ENCRYPTED.to_vec()]),
        &mut sink,
        weaver_graph::Budget::default(),
    );
    assert!(said(&emits).contains(&Said::Closed(0)));
    assert_eq!(checksums(&emits), Vec::new());
}

// The volumes, recording where every read a run makes of them starts.
struct Counted {
    gate: Arc<Gate>,
    reads: Mutex<Vec<(u32, u64)>>,
}

impl Volumes for Counted {
    fn next(&self, after: Option<VolumeIndex>) -> io::Result<Option<VolumeIndex>> {
        self.gate.next(after)
    }

    fn len(&self, volume: VolumeIndex) -> Option<u64> {
        self.gate.len(volume)
    }

    fn settled(&self, volume: VolumeIndex) -> bool {
        self.gate.settled(volume)
    }

    fn read_at(&self, volume: VolumeIndex, offset: u64, into: &mut [u8]) -> io::Result<usize> {
        self.reads.lock().unwrap().push((volume.0, offset));
        self.gate.read_at(volume, offset, into)
    }
}

// A pool that lends threads of its own, recording how many each spread
// asked for, and how many each spread beside the run's thread started.
#[derive(Default)]
struct Lent {
    spreads: Mutex<Vec<usize>>,
    besides: Mutex<Vec<usize>>,
}

impl weaver_graph::Pool for Lent {
    fn spread(&self, workers: usize, work: &(dyn Fn() + Sync)) {
        self.spreads.lock().unwrap().push(workers);
        thread::scope(|scope| {
            for _ in 0..workers {
                scope.spawn(work);
            }
        });
    }

    fn spread_beside(&self, work: &(dyn Fn() + Sync), caller: &mut dyn FnMut(&dyn Fn())) {
        let started = std::sync::atomic::AtomicUsize::new(0);
        thread::scope(|scope| {
            caller(&|| {
                started.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                scope.spawn(work);
            });
        });
        self.besides.lock().unwrap().push(started.into_inner());
    }
}

// What a run on `threads` of a lent pool said.
struct OnThreads {
    said: Vec<Said>,
    sums: Vec<(u32, u32)>,
    // Where each read started, in the order made.
    reads: Vec<(u32, u64)>,
    // The threads each spread asked of the pool.
    spreads: Vec<usize>,
    // The workers each spread beside the run's thread started.
    besides: Vec<usize>,
}

impl OnThreads {
    // The reads of volume 0's first bytes: one for each archive opened.
    fn opens(&self) -> usize {
        self.reads.iter().filter(|read| **read == (0, 0)).count()
    }
}

// Six stored files over two volumes, three in each, of the set's flags.
fn six_files(flags: u64) -> Vec<Vec<u8>> {
    six_files_as(flags, 0)
}

// The six files, their headers naming the fastest method and the smallest
// dictionary, 128 KiB. Their data is not compressed: the tests that use
// them look at how the run lays its work out, not at what it decodes.
fn six_files_compressed() -> Vec<Vec<u8>> {
    six_files_as(0, 1 << 7)
}

fn six_files_as(flags: u64, compression: u64) -> Vec<Vec<u8>> {
    vec![
        [
            rar5::start_flagged(flags, 0),
            stored(0..3, compression),
            rar5::end(true),
        ]
        .concat(),
        [
            rar5::start_flagged(flags, 1),
            stored(3..6, compression),
            rar5::end(false),
        ]
        .concat(),
    ]
}

// The six stored files in one volume.
fn six_in_one() -> Vec<Vec<u8>> {
    vec![[rar5::start_flagged(0, 0), stored(0..6, 0), rar5::end(false)].concat()]
}

// The files numbered `files`, each with its header and its data.
fn stored(files: std::ops::Range<u8>, compression: u64) -> Vec<u8> {
    let body = |at: u8| -> Vec<u8> {
        (0..200u16 + u16::from(at) * 37)
            .map(|byte| (byte as u8) ^ at)
            .collect()
    };
    files
        .flat_map(|at| {
            let bytes = body(at);
            rar5::file_as(
                &format!("file{at}.bin"),
                0,
                &bytes,
                bytes.len() as u64,
                Some(crc32(&bytes)),
                compression,
            )
        })
        .collect()
}

fn on_budget(volumes: Vec<Vec<u8>>, memory_bytes: Option<u64>, threads: usize) -> OnThreads {
    let counted = Arc::new(Counted {
        gate: Gate::whole(volumes),
        reads: Mutex::new(Vec::new()),
    });
    let lent = Arc::new(Lent::default());
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    RarEngine::new().start().run(
        Arc::clone(&counted) as Arc<dyn Volumes>,
        &mut sink,
        weaver_graph::Budget {
            memory_bytes,
            window_bytes: None,
            threads,
            pool: Some(Arc::clone(&lent) as Arc<dyn weaver_graph::Pool>),
            lender: None,
            ..Default::default()
        },
    );
    let reads = std::mem::take(&mut *counted.reads.lock().unwrap());
    let spreads = std::mem::take(&mut *lent.spreads.lock().unwrap());
    let besides = std::mem::take(&mut *lent.besides.lock().unwrap());
    OnThreads {
        said: said(&emits),
        sums: checksums(&emits),
        reads,
        spreads,
        besides,
    }
}

fn on_threads(volumes: Vec<Vec<u8>>, threads: usize) -> OnThreads {
    on_budget(volumes, None, threads)
}

#[test]
fn a_compressed_member_larger_than_the_run_memory_budget_is_refused() {
    let archive = include_bytes!(
        "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar5_lz.rar"
    );
    let result = on_budget(vec![archive.to_vec()], Some(1), 1);
    assert!(
        result.said.contains(&Said::Refuse(Why::TooLarge {
            needed: Some(256 << 10),
            allowed: Some(1),
        })),
        "{:?}",
        result.said
    );
    assert!(
        !result
            .said
            .iter()
            .any(|said| matches!(said, Said::Bytes(_, _)))
    );
}

const MIB: u64 = 1 << 20;
const GIB: u64 = 1 << 30;

// A run as each hardware profile grants it: its memory and the window one
// decoder may hold, Efficient, Balanced and Performance in turn.
fn profiles() -> [weaver_graph::Budget; 3] {
    [(512 * MIB, 256 * MIB), (GIB, GIB), (4 * GIB, 4 * GIB)].map(|(memory, window)| {
        weaver_graph::Budget {
            memory_bytes: Some(memory),
            window_bytes: Some(window),
            threads: 1,
            ..Default::default()
        }
    })
}

// The dictionary limit is the window the profile grants. A RAR3 PPMd arena
// keeps the format's 256 MiB ceiling on every profile. A run granted no
// window keeps the decoder's own 256 MiB, narrowed by the memory granted.
#[test]
fn each_profiles_window_is_the_rar_dictionary_limit() {
    let [efficient, balanced, performance] = profiles().map(|budget| run::limits(&budget));
    assert_eq!(efficient.max_dict_size, 256 * MIB);
    assert_eq!(balanced.max_dict_size, GIB);
    assert_eq!(performance.max_dict_size, 4 * GIB);
    for limits in [&efficient, &balanced, &performance] {
        assert_eq!(limits.max_ppmd_arena_size, 256 * MIB);
    }
    let own = run::limits(&weaver_graph::Budget::default());
    assert_eq!(own.max_dict_size, 256 * MIB);
    let narrow = run::limits(&weaver_graph::Budget {
        memory_bytes: Some(64 * MIB),
        window_bytes: Some(GIB),
        ..Default::default()
    });
    assert_eq!(narrow.max_dict_size, 64 * MIB);
    assert_eq!(narrow.max_ppmd_arena_size, 64 * MIB);
}

// A compressed member whose header names a 1 GiB dictionary: RAR5 method 1,
// dictionary 128 KiB << 13. Its data is never decoded.
fn one_gib_dictionary() -> Vec<u8> {
    [
        rar5::start(None),
        rar5::file_as("wide.bin", 0, &[0; 64], MIB, None, (1 << 7) | (13 << 10)),
        rar5::end(false),
    ]
    .concat()
}

// The header's dictionary fits the Balanced and Performance limits and not
// the Efficient one, and an Efficient run refuses the member before it
// holds any window.
#[test]
fn a_one_gib_rar_dictionary_is_refused_only_under_efficient() {
    let archive = unrar_rs::RarArchive::open_prefix(
        io::Cursor::new(one_gib_dictionary()),
        None,
        NonZeroUsize::MIN,
    )
    .unwrap();
    let dictionary = archive.member_info(0).unwrap().compression.dict_size;
    assert_eq!(dictionary, GIB);
    let fits = profiles().map(|budget| dictionary <= run::limits(&budget).max_dict_size);
    assert_eq!(fits, [false, true, true]);

    let [efficient, ..] = profiles();
    let mut emits = Vec::new();
    RarEngine::new().start().run(
        Gate::whole(vec![one_gib_dictionary()]) as Arc<dyn Volumes>,
        &mut |emit| {
            emits.push(emit);
            true
        },
        efficient,
    );
    let said = said(&emits);
    assert!(
        said.contains(&Said::Refuse(Why::TooLarge {
            needed: Some(GIB),
            allowed: Some(256 * MIB),
        })),
        "{said:?}"
    );
    assert!(!said.iter().any(|said| matches!(said, Said::Bytes(_, _))));
}

#[test]
fn the_files_of_a_set_that_is_not_solid_decode_side_by_side_and_are_said_in_order() {
    let alone = on_threads(six_files(0), 1);
    let beside = on_threads(six_files(0), 4);
    let ids: Vec<u32> = alone
        .said
        .iter()
        .filter_map(|said| match said {
            Said::Member(id, _, _) => Some(*id),
            _ => None,
        })
        .collect();
    assert_eq!(ids, (0..6).collect::<Vec<_>>());
    assert!(alone.said.contains(&Said::Closed(5)));
    // Each file states the CRC32 of the bytes it delivered.
    let delivered: Vec<(u32, u32)> = alone
        .said
        .iter()
        .filter_map(|said| match said {
            Said::Bytes(id, bytes) => Some((*id, crc32(bytes))),
            _ => None,
        })
        .collect();
    assert_eq!(alone.sums, delivered);
    assert_eq!(beside.said, alone.said);
    assert_eq!(beside.sums, alone.sums);
    // The first volume's files wait for the next volume's headers, whose
    // bytes are all in, and five files decode in one spread, on no more
    // workers than the four threads. The last waits for the header after
    // it, and that is the set's end record, so it decodes alone.
    assert!(alone.spreads.is_empty(), "{:?}", alone.spreads);
    assert_eq!(beside.spreads, vec![4]);
    // The workers decoded over the headers the walk parsed: none opened
    // the set again.
    assert_eq!(beside.opens(), alone.opens());
}

// Four files over three volumes, the second and third running on from one
// volume into the next.
fn spanning_files() -> Vec<Vec<u8>> {
    let body = |at: u8| -> Vec<u8> { (0..300u16).map(|byte| (byte as u8) ^ at).collect() };
    let whole = |at: u8, flags: u64, part: &[u8]| {
        let bytes = body(at);
        rar5::file(
            &format!("file{at}.bin"),
            flags,
            part,
            bytes.len() as u64,
            (flags & rar5::SPLIT_AFTER == 0).then(|| crc32(&bytes)),
        )
    };
    let (one, two) = (body(1), body(2));
    vec![
        [
            rar5::start(Some(0)),
            whole(0, 0, &body(0)),
            whole(1, rar5::SPLIT_AFTER, &one[..100]),
            rar5::end(true),
        ]
        .concat(),
        [
            rar5::start(Some(1)),
            whole(1, rar5::SPLIT_BEFORE, &one[100..]),
            whole(2, rar5::SPLIT_AFTER, &two[..150]),
            rar5::end(true),
        ]
        .concat(),
        [
            rar5::start(Some(2)),
            whole(2, rar5::SPLIT_BEFORE, &two[150..]),
            whole(3, 0, &body(3)),
            rar5::end(false),
        ]
        .concat(),
    ]
}

// Files that run on from one volume into the next decode side by side once
// every volume they span is in, as a file whole in one volume does: the
// walk reads the next volume's headers before it decides.
#[test]
fn files_spanning_volumes_whose_bytes_are_all_in_decode_side_by_side() {
    let alone = on_threads(spanning_files(), 1);
    let beside = on_threads(spanning_files(), 4);
    assert!(alone.said.contains(&Said::Closed(3)), "{:?}", alone.said);
    assert_eq!(beside.said, alone.said);
    assert_eq!(beside.sums, alone.sums);
    // The first three files decode in one spread. The last waits for the
    // header after it, and that is the set's end record, so it decodes
    // alone.
    assert_eq!(beside.spreads, vec![3]);
    assert_eq!(beside.opens(), alone.opens());
}

#[test]
fn a_run_spreads_no_wider_than_the_threads_it_was_granted() {
    let beside = on_threads(six_in_one(), 2);
    assert_eq!(beside.said, on_threads(six_in_one(), 1).said);
    assert!(!beside.spreads.is_empty());
    assert!(
        beside.spreads.iter().all(|&workers| workers <= 2),
        "{:?}",
        beside.spreads
    );
}

#[test]
fn a_volume_whose_bytes_are_not_all_in_decodes_one_by_one() {
    // The volumes are closed, so their lengths are known, but their bytes
    // are not all in: a worker on the lent pool would wait on them.
    struct Unsettled(Arc<Gate>);
    impl Volumes for Unsettled {
        fn next(&self, after: Option<VolumeIndex>) -> io::Result<Option<VolumeIndex>> {
            self.0.next(after)
        }
        fn len(&self, volume: VolumeIndex) -> Option<u64> {
            self.0.len(volume)
        }
        fn read_at(&self, volume: VolumeIndex, offset: u64, into: &mut [u8]) -> io::Result<usize> {
            self.0.read_at(volume, offset, into)
        }
    }
    let lent = Arc::new(Lent::default());
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    RarEngine::new().start().run(
        Arc::new(Unsettled(Gate::whole(six_files(0)))),
        &mut sink,
        weaver_graph::Budget {
            memory_bytes: None,
            window_bytes: None,
            threads: 4,
            pool: Some(Arc::clone(&lent) as Arc<dyn weaver_graph::Pool>),
            lender: None,
            ..Default::default()
        },
    );
    assert_eq!(said(&emits), on_threads(six_files(0), 1).said);
    assert!(lent.spreads.lock().unwrap().is_empty());
}

#[test]
fn a_solid_set_decodes_one_member_after_another_whatever_the_threads() {
    let alone = on_threads(six_files(rar5::SOLID), 1);
    let beside = on_threads(six_files(rar5::SOLID), 4);
    assert!(alone.said.contains(&Said::Closed(5)), "{:?}", alone.said);
    assert_eq!(beside.said, alone.said);
    assert_eq!(beside.sums, alone.sums);
    assert!(beside.spreads.is_empty(), "{:?}", beside.spreads);
}

#[test]
fn files_that_do_not_fit_the_budgets_memory_together_decode_one_by_one() {
    // No two files fit in 300 bytes.
    let beside = on_budget(six_files(0), Some(300), 4);
    assert_eq!(beside.said, on_threads(six_files(0), 1).said);
    assert!(beside.spreads.is_empty(), "{:?}", beside.spreads);
}

#[test]
fn a_compressed_files_decoder_window_counts_against_the_budgets_memory() {
    // Three files of a few hundred bytes each fit in 4 KiB as bytes, but
    // not beside the 128 KiB window their compressed headers name.
    let small = on_budget(six_files_compressed(), Some(4096), 4);
    assert!(small.spreads.is_empty(), "{:?}", small.spreads);
    let roomy = on_budget(six_files_compressed(), Some(1 << 20), 4);
    assert!(!roomy.spreads.is_empty());
}

#[test]
fn a_file_that_fails_beside_others_ends_the_run_as_it_would_alone() {
    let damaged = || {
        let mut volumes = six_files(0);
        let body: Vec<u8> = (0..237u16).map(|byte| (byte as u8) ^ 1).collect();
        let at = volumes[0]
            .windows(body.len())
            .position(|window| window == body)
            .unwrap();
        volumes[0][at + 5] ^= 0x20;
        volumes
    };
    let OnThreads { said: alone, .. } = on_threads(damaged(), 1);
    let OnThreads {
        said: beside,
        spreads,
        ..
    } = on_threads(damaged(), 4);
    let length = damaged()[0].len() as u64;
    assert_eq!(
        alone[alone.len() - 2..],
        [Said::Retract(1), Said::Damaged(0, 0, length)]
    );
    assert!(alone.contains(&Said::Closed(0)));
    assert!(!alone.contains(&Said::Member(2, "file2.bin".into(), Some(274))));
    // Beside others the failing file is decoded whole first, and then said
    // as it streamed out alone: its bytes, as far as its decode came, before
    // its checksum fails and it is retracted.
    assert_eq!(beside, alone);
    assert!(!spreads.is_empty());
}

// The gate's volumes as unrar-rs reads them, each read waiting for its
// volume's bytes as a run's does.
struct Gated(Arc<Gate>);

struct GatedReader {
    gate: Arc<Gate>,
    volume: VolumeIndex,
    position: u64,
}

impl io::Read for GatedReader {
    fn read(&mut self, into: &mut [u8]) -> io::Result<usize> {
        let read = self.gate.read_at(self.volume, self.position, into)?;
        self.position += read as u64;
        Ok(read)
    }
}

impl io::Seek for GatedReader {
    fn seek(&mut self, from: io::SeekFrom) -> io::Result<u64> {
        self.position = match from {
            io::SeekFrom::Start(offset) => offset,
            io::SeekFrom::Current(by) => self.position.checked_add_signed(by).unwrap(),
            io::SeekFrom::End(by) => (self.gate.volumes[self.volume.0 as usize].len() as u64)
                .checked_add_signed(by)
                .unwrap(),
        };
        Ok(self.position)
    }
}

impl unrar_rs::VolumeProvider for Gated {
    fn get_volume(
        &self,
        index: usize,
    ) -> Result<Box<dyn unrar_rs::ReadSeek>, unrar_rs::VolumeProviderError> {
        Ok(Box::new(GatedReader {
            gate: Arc::clone(&self.0),
            volume: VolumeIndex(index as u32),
            position: 0,
        }))
    }
}

// An archive made from the headers of a prefix read only as far as a
// member's first part decodes that member whole: its continuations are
// found as decoding reaches the volumes that hold them, though none was
// parsed when the copy was made and none of those volumes was in yet.
#[test]
fn a_copy_of_the_headers_decodes_a_member_whose_continuations_it_never_parsed() {
    let rar5_four: Vec<Vec<u8>> = (1..=4)
        .map(|part| {
            std::fs::read(format!(
                "{}/../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar5_lz_four.part0{part}.rar",
                env!("CARGO_MANIFEST_DIR")
            ))
            .unwrap()
        })
        .collect();
    let rar4_four: Vec<Vec<u8>> = SPLIT_LZ.iter().map(|volume| volume.to_vec()).collect();
    for volumes in [rar4_four, rar5_four] {
        let count = volumes.len() as u32;
        let whole = Gate::whole(volumes.clone());
        let mut full = unrar_rs::RarArchive::open_prefix(
            GatedReader {
                gate: Arc::clone(&whole),
                volume: VolumeIndex(0),
                position: 0,
            },
            None,
            NonZeroUsize::MIN,
        )
        .unwrap();
        let mut expected = Vec::new();
        full.by_index_via(0, &Gated(Arc::clone(&whole)))
            .and_then(|entry| entry.copy_to(&mut expected))
            .unwrap();
        assert!(!expected.is_empty());

        let mut released = vec![false; volumes.len()];
        released[0] = true;
        let gate = Gate::new(volumes, &released);
        let prefix = unrar_rs::RarArchive::open_prefix(
            GatedReader {
                gate: Arc::clone(&gate),
                volume: VolumeIndex(0),
                position: 0,
            },
            None,
            NonZeroUsize::MIN,
        )
        .unwrap();
        let first = prefix.member_info(0).unwrap();
        assert_eq!(
            (first.volumes.first_volume, first.volumes.last_volume),
            (0, 0),
            "the copy knows the member's first part only"
        );
        let mut copy = unrar_rs::RarArchive::from_cached_headers_with_password_and_shared_kdf_cache(
            prefix.export_headers(),
            None,
            Arc::new(KdfCache::new()),
        );
        copy.set_verify(true);
        let provider = Gated(Arc::clone(&gate));
        let decoding = thread::spawn(move || {
            let mut out = Vec::new();
            copy.by_index_via(0, &provider)
                .and_then(|entry| entry.copy_to(&mut out))
                .map(|_| out)
        });
        for volume in 1..count {
            gate.wait_for_reader(volume);
            gate.release(volume);
        }
        assert_eq!(decoding.join().unwrap().unwrap(), expected);
    }
}

// A file posted over three volumes, then three files whole in the last;
// `flip` names a file one byte of whose last part is posted wrong.
fn overlapping(flip: Option<u8>) -> Vec<Vec<u8>> {
    let body = |at: u8, length: usize| -> Vec<u8> {
        (0..length)
            .map(|byte| (byte as u8).wrapping_mul(3) ^ at)
            .collect()
    };
    let posted = |at: u8, bytes: &[u8]| -> Vec<u8> {
        let mut posted = bytes.to_vec();
        if flip == Some(at) {
            posted[5] ^= 0x20;
        }
        posted
    };
    let whole = |at: u8| {
        let bytes = body(at, 400 + usize::from(at) * 50);
        rar5::file(
            &format!("file{at}.bin"),
            0,
            &posted(at, &bytes),
            bytes.len() as u64,
            Some(crc32(&bytes)),
        )
    };
    let first = body(0, 3000);
    let length = first.len() as u64;
    vec![
        [
            rar5::start(Some(0)),
            rar5::file("file0.bin", rar5::SPLIT_AFTER, &first[..1000], length, None),
            rar5::end(true),
        ]
        .concat(),
        [
            rar5::start(Some(1)),
            rar5::file(
                "file0.bin",
                rar5::SPLIT_BEFORE | rar5::SPLIT_AFTER,
                &first[1000..2000],
                length,
                None,
            ),
            rar5::end(true),
        ]
        .concat(),
        [
            rar5::start(Some(2)),
            rar5::file(
                "file0.bin",
                rar5::SPLIT_BEFORE,
                &posted(0, &first[2000..]),
                length,
                Some(crc32(&first)),
            ),
            whole(1),
            whole(2),
            whole(3),
            rar5::end(false),
        ]
        .concat(),
    ]
}

// A run over `volumes` on `threads` of `pool`, the first volume in when it
// starts, and the rest once the run waits on the second.
fn arriving_on(
    volumes: Vec<Vec<u8>>,
    threads: usize,
    pool: Arc<dyn weaver_graph::Pool>,
) -> Vec<Emit> {
    let mut released = vec![false; volumes.len()];
    released[0] = true;
    let count = volumes.len() as u32;
    let gate = Gate::new(volumes, &released);
    thread::scope(|scope| {
        let run = scope.spawn(|| {
            let mut emits = Vec::new();
            let mut sink = |emit| {
                emits.push(emit);
                true
            };
            RarEngine::new().start().run(
                Arc::clone(&gate) as Arc<dyn Volumes>,
                &mut sink,
                weaver_graph::Budget {
                    memory_bytes: None,
                    window_bytes: None,
                    threads,
                    pool: Some(pool),
                    lender: None,
                    ..Default::default()
                },
            );
            emits
        });
        gate.wait_for_reader(1);
        for volume in 1..count {
            gate.release(volume);
        }
        run.join().unwrap()
    })
}

fn arriving(volumes: Vec<Vec<u8>>, threads: usize) -> OnThreads {
    let lent = Arc::new(Lent::default());
    let emits = arriving_on(
        volumes,
        threads,
        Arc::clone(&lent) as Arc<dyn weaver_graph::Pool>,
    );
    OnThreads {
        said: said(&emits),
        sums: checksums(&emits),
        reads: Vec::new(),
        spreads: std::mem::take(&mut *lent.spreads.lock().unwrap()),
        besides: std::mem::take(&mut *lent.besides.lock().unwrap()),
    }
}

// A file decoding on the run's thread while the last of its volumes come in
// holds back none of the files after it: once their bytes are in, they
// decode beside it, and every file is said as if one by one.
#[test]
fn files_after_one_still_decoding_decode_beside_it_and_are_said_in_order() {
    let alone = arriving(overlapping(None), 1);
    let beside = arriving(overlapping(None), 4);
    assert!(alone.said.contains(&Said::Closed(3)), "{:?}", alone.said);
    assert_eq!(beside.said, alone.said);
    assert_eq!(beside.sums, alone.sums);
    assert!(alone.besides.is_empty(), "{:?}", alone.besides);
    // The second and third files decode beside the first. The last waits
    // for the header after it, the set's end record, so it decodes alone.
    assert_eq!(beside.besides, vec![2, 0]);
    assert!(beside.spreads.is_empty(), "{:?}", beside.spreads);
}

// A file that fails beside one still decoding fails the run only once that
// one closes, and as it would have failed alone.
#[test]
fn a_file_that_fails_beside_one_still_decoding_fails_the_run_after_it_closes() {
    let alone = arriving(overlapping(Some(2)), 1);
    let beside = arriving(overlapping(Some(2)), 4);
    assert!(alone.said.contains(&Said::Closed(1)), "{:?}", alone.said);
    assert!(alone.said.contains(&Said::Retract(2)), "{:?}", alone.said);
    assert_eq!(beside.said, alone.said);
    assert_eq!(beside.besides, vec![2]);
}

// The file on the run's thread fails: the files decoded beside it are never
// said, as the walk would never have reached them.
#[test]
fn files_decoded_beside_one_that_fails_are_never_said() {
    let alone = arriving(overlapping(Some(0)), 1);
    let beside = arriving(overlapping(Some(0)), 4);
    assert!(alone.said.contains(&Said::Retract(0)), "{:?}", alone.said);
    assert!(
        !alone
            .said
            .iter()
            .any(|said| matches!(said, Said::Member(1.., _, _))),
        "{:?}",
        alone.said
    );
    assert_eq!(beside.said, alone.said);
    assert_eq!(beside.besides, vec![2]);
}

// A pool whose workers beside the run's thread wait to be let go, so a test
// can stop the run while they are out.
#[derive(Default)]
struct Held {
    state: Mutex<(usize, bool, usize)>,
    changed: Condvar,
}

impl Held {
    fn started(&self) -> usize {
        self.state.lock().unwrap().0
    }

    fn wait_started(&self) {
        let mut state = self.state.lock().unwrap();
        while state.0 == 0 {
            state = self.changed.wait(state).unwrap();
        }
    }

    fn let_go(&self) {
        self.state.lock().unwrap().1 = true;
        self.changed.notify_all();
    }

    fn returned(&self) -> usize {
        self.state.lock().unwrap().2
    }
}

impl weaver_graph::Pool for Held {
    fn spread(&self, workers: usize, work: &(dyn Fn() + Sync)) {
        thread::scope(|scope| {
            for _ in 0..workers {
                scope.spawn(work);
            }
        });
    }

    fn spread_beside(&self, work: &(dyn Fn() + Sync), caller: &mut dyn FnMut(&dyn Fn())) {
        thread::scope(|scope| {
            caller(&|| {
                self.state.lock().unwrap().0 += 1;
                self.changed.notify_all();
                scope.spawn(|| {
                    let mut state = self.state.lock().unwrap();
                    while !state.1 {
                        state = self.changed.wait(state).unwrap();
                    }
                    drop(state);
                    work();
                    self.state.lock().unwrap().2 += 1;
                });
            });
        });
    }
}

// The owner stops a run while files decode beside it: the run returns only
// once every worker has, nothing it says after is heard, and the next run
// says the set from its first file.
#[test]
fn a_run_stopped_while_files_decode_beside_it_joins_them_and_the_next_says_all() {
    let held = Arc::new(Held::default());
    let mut released = vec![false; 3];
    released[0] = true;
    let gate = Gate::new(overlapping(None), &released);
    let after = std::sync::atomic::AtomicUsize::new(0);
    let returned = thread::scope(|scope| {
        let run = scope.spawn(|| {
            let mut stopped = false;
            let mut sink = |_emit| {
                if stopped {
                    after.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    return false;
                }
                stopped = held.started() > 0;
                !stopped
            };
            RarEngine::new().start().run(
                Arc::clone(&gate) as Arc<dyn Volumes>,
                &mut sink,
                weaver_graph::Budget {
                    memory_bytes: None,
                    window_bytes: None,
                    threads: 4,
                    pool: Some(Arc::clone(&held) as Arc<dyn weaver_graph::Pool>),
                    lender: None,
                    ..Default::default()
                },
            );
            held.returned()
        });
        gate.wait_for_reader(1);
        gate.release(1);
        gate.release(2);
        held.wait_started();
        held.let_go();
        run.join().unwrap()
    });
    assert_eq!(returned, held.started());
    assert_eq!(after.load(std::sync::atomic::Ordering::Relaxed), 0);
    let alone = on_threads(overlapping(None), 1);
    assert_eq!(arriving(overlapping(None), 4).said, alone.said);
}

// How a set's volumes come in while a run reads them.
#[derive(Clone, Copy, Debug)]
enum Arrival {
    // All in before the run starts.
    Whole,
    // Each as the run first reads it, with as many after it as the
    // download is ahead.
    Ahead(u32),
}

// Volumes that come in as the run first reads them.
struct Dripping {
    gate: Arc<Gate>,
    ahead: u32,
}

impl Volumes for Dripping {
    fn next(&self, after: Option<VolumeIndex>) -> io::Result<Option<VolumeIndex>> {
        self.gate.next(after)
    }

    fn len(&self, volume: VolumeIndex) -> Option<u64> {
        self.gate.len(volume)
    }

    fn settled(&self, volume: VolumeIndex) -> bool {
        self.gate.settled(volume)
    }

    fn read_at(&self, volume: VolumeIndex, offset: u64, into: &mut [u8]) -> io::Result<usize> {
        if !self.gate.settled(volume) {
            let last = (self.gate.volumes.len() as u32).saturating_sub(1);
            for at in volume.0..=volume.0.saturating_add(self.ahead).min(last) {
                self.gate.release(at);
            }
        }
        self.gate.read_at(volume, offset, into)
    }
}

fn arrived(
    volumes: &[Vec<u8>],
    password: Option<&str>,
    arrival: Arrival,
    threads: usize,
) -> (Vec<Said>, Vec<(u32, u32)>) {
    let volumes: Arc<dyn Volumes> = match arrival {
        Arrival::Whole => Gate::whole(volumes.to_vec()),
        Arrival::Ahead(ahead) => Arc::new(Dripping {
            gate: Gate::new(volumes.to_vec(), &vec![false; volumes.len()]),
            ahead,
        }),
    };
    let mut emits = Vec::new();
    let mut sink = |emit| {
        emits.push(emit);
        true
    };
    let lent = Arc::new(Lent::default());
    let mut engine = RarEngine::new();
    if let Some(password) = password {
        engine.offer_password(password, &mut Vec::new());
    }
    engine.start().run(
        volumes,
        &mut sink,
        weaver_graph::Budget {
            memory_bytes: None,
            window_bytes: None,
            threads,
            pool: Some(lent as Arc<dyn weaver_graph::Pool>),
            lender: None,
            ..Default::default()
        },
    );
    (said(&emits), checksums(&emits))
}

// The RAR sets of the test corpus small enough for the default suite, each
// with its volumes in order.
fn fixture_sets() -> Vec<(String, Vec<Vec<u8>>)> {
    let root = format!(
        "{}/../../server/crates/weaver-server-core/tests/fixtures",
        env!("CARGO_MANIFEST_DIR")
    );
    let mut sets: BTreeMap<String, Vec<(String, Vec<u8>)>> = BTreeMap::new();
    for dir in ["extraction_profiles", "rar4", "rar5"] {
        for entry in std::fs::read_dir(format!("{root}/{dir}")).unwrap() {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            if !name.ends_with(".rar") || std::fs::metadata(&path).unwrap().len() > 1 << 20 {
                continue;
            }
            let set = match name.rsplit_once(".part") {
                Some((set, _)) => set.to_owned(),
                None => name.trim_end_matches(".rar").to_owned(),
            };
            sets.entry(format!("{dir}/{set}"))
                .or_default()
                .push((name, std::fs::read(&path).unwrap()));
        }
    }
    sets.into_iter()
        .map(|(set, mut volumes)| {
            volumes.sort();
            (set, volumes.into_iter().map(|(_, bytes)| bytes).collect())
        })
        .collect()
}

// The direct store's writer layouts: stored files over one volume and many,
// enciphered files and headers, solid, and a file whose header names a
// method its bytes were not made with.
fn writer_sets() -> Vec<(String, Vec<Vec<u8>>)> {
    use crate::rar_store::tests::writer::{Item, Options, Version, write};
    let items: Vec<Item> = (0..6u64)
        .map(|at| {
            Item::File(
                ["a.bin", "b.bin", "c.bin", "d.bin", "e.bin", "f.bin"][at as usize],
                crate::testing::payload(at + 1, 700 + 2_900 * at as usize),
            )
        })
        .collect();
    // How a layout sets the writer's options.
    type Shape = fn(&mut Options);
    let mut sets = Vec::new();
    for version in [Version::Rar4, Version::Rar5] {
        let shapes: [(&str, Shape); 8] = [
            ("one", |_| {}),
            ("split", |options| options.split = Some(6_000)),
            ("encrypted", |options| options.password = Some(PASSWORD)),
            ("split-encrypted", |options| {
                options.split = Some(6_000);
                options.password = Some(PASSWORD);
            }),
            ("split-headers", |options| {
                options.split = Some(6_000);
                options.password = Some(PASSWORD);
                options.encrypt_headers = true;
            }),
            ("split-solid", |options| {
                options.split = Some(6_000);
                options.solid = true;
            }),
            ("split-compressed", |options| {
                options.split = Some(6_000);
                options.compressed = Some(3);
            }),
            ("split-recovery", |options| {
                options.split = Some(6_000);
                options.recovery = true;
            }),
        ];
        for (shape, made) in shapes {
            let mut options = Options::new(version);
            made(&mut options);
            sets.push((format!("{version:?}-{shape}"), write(&items, &options)));
        }
    }
    sets
}

const PASSWORD: &str = "testpass123";

// Every set the engine's tests read, from the corpus, the store's writer and
// the layouts above, plus each multi-volume one with a byte of its last
// volume posted wrong, is said alike by the walk on one thread and on many,
// emit for emit and in order, whether its volumes are all in or come in as
// it reads.
#[test]
fn the_walk_says_every_set_alike_on_one_thread_and_on_many() {
    let mut sets = fixture_sets();
    assert!(sets.len() >= 40, "{} sets", sets.len());
    sets.extend(writer_sets());
    sets.extend([
        ("six".to_owned(), six_files(0)),
        ("six-solid".to_owned(), six_files(rar5::SOLID)),
        ("six-compressed".to_owned(), six_files_compressed()),
        ("six-in-one".to_owned(), six_in_one()),
        ("spanning".to_owned(), spanning_files()),
        ("overlapping".to_owned(), overlapping(None)),
        ("overlapping-first-wrong".to_owned(), overlapping(Some(0))),
        ("overlapping-third-wrong".to_owned(), overlapping(Some(2))),
    ]);
    let damaged: Vec<(String, Vec<Vec<u8>>)> = sets
        .iter()
        .filter(|(_, volumes)| volumes.len() > 1)
        .map(|(name, volumes)| {
            let mut volumes = volumes.clone();
            let last = volumes.last_mut().unwrap();
            let middle = last.len() / 2;
            last[middle] ^= 0x10;
            (format!("{name}-damaged"), volumes)
        })
        .collect();
    sets.extend(damaged);
    for (name, volumes) in &sets {
        for password in [None, Some(PASSWORD)] {
            for arrival in [Arrival::Whole, Arrival::Ahead(0), Arrival::Ahead(2)] {
                let alone = arrived(volumes, password, arrival, 1);
                for threads in [2, 4] {
                    let beside = arrived(volumes, password, arrival, threads);
                    assert!(
                        beside == alone,
                        "{name} {password:?} {arrival:?} on {threads} threads: {:?} {:?} alone {:?} {:?}",
                        brief(&beside.0),
                        beside.1,
                        brief(&alone.0),
                        alone.1
                    );
                }
            }
        }
    }
}

// What a run said, with each member's bytes as their length and checksum.
fn brief(said: &[Said]) -> Vec<String> {
    said.iter()
        .map(|said| match said {
            Said::Bytes(id, bytes) => format!("Bytes({id}, {} {:08x})", bytes.len(), crc32(bytes)),
            other => format!("{other:?}"),
        })
        .collect()
}

// A compressed member reaches the sink in pieces of at least a megabyte, its
// last aside, not in the tails the decoder writes beside each window it
// flushes.
#[test]
fn a_compressed_member_is_said_in_megabyte_pieces() {
    for archive in [
        include_bytes!(
            "../../../../server/crates/weaver-server-core/tests/fixtures/rar4/rar4_solid.rar"
        )
        .as_slice(),
        include_bytes!(
            "../../../../server/crates/weaver-server-core/tests/fixtures/rar5/rar5_solid.rar"
        )
        .as_slice(),
    ] {
        let mut emits = Vec::new();
        let mut sink = |emit| {
            emits.push(emit);
            true
        };
        RarEngine::new().start().run(
            Gate::whole(vec![archive.to_vec()]),
            &mut sink,
            weaver_graph::Budget::default(),
        );
        let mut pieces: BTreeMap<u32, Vec<usize>> = BTreeMap::new();
        for emit in &emits {
            if let Emit::Bytes { member, bytes, .. } = emit {
                pieces.entry(member.0).or_default().push(bytes.len());
            }
        }
        assert!(pieces.values().any(|lengths| lengths.len() > 1));
        for lengths in pieces.values() {
            let (_, before_last) = lengths.split_last().unwrap();
            assert!(
                before_last
                    .iter()
                    .all(|length| *length >= super::run::EMIT_BYTES),
                "{lengths:?}"
            );
        }
    }
}

// A volume whose one compressed member names a 1 GiB dictionary, RAR5
// method 1, and unpacks to 64 KiB; `flags` are the archive's.
fn wide_dictionary_small_member(flags: u64) -> Vec<u8> {
    [
        rar5::start_flagged(flags, 0),
        rar5::file_as(
            "small.bin",
            0,
            &[0; 64],
            64 << 10,
            None,
            (1 << 7) | (13 << 10),
        ),
        rar5::end(true),
    ]
    .concat()
}

fn reserved(front: &[u8]) -> Option<u64> {
    let mut engine = RarEngine::new();
    engine.bound(VolumeIndex(0), "lantern.part1.rar", front, None);
    engine.reserve()
}

// A run reserves what its decode will hold: the dictionary the header
// declares or the member's whole unpacked size, the less. A solid archive
// keeps one window across members no front sums, so it holds the whole
// dictionary. A front that states no compressed member reserves nothing
// past the format's own.
#[test]
fn a_small_member_of_a_wide_dictionary_reserves_its_own_size() {
    assert_eq!(reserved(&wide_dictionary_small_member(0)), Some(64 << 10));
    assert_eq!(
        reserved(&wide_dictionary_small_member(rar5::SOLID)),
        Some(GIB)
    );
    assert_eq!(reserved(&six_files(0)[0]), Some(0));
    assert_eq!(reserved(&[]), Some(0));
}

// RAR5 LZ, one member under a 256 KiB dictionary.
const LZ: &[u8] = include_bytes!(
    "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar5_lz.rar"
);
// RAR 2.9 solid PPMd: three members, a 1 MiB dictionary and a 1 MiB model
// arena (`-m5 -mc16:1t+ -md1m`).
const PPMD: &[u8] = include_bytes!(
    "../../../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/rar4_solid_ppmd_plain.rar"
);

// A run over `archive` granted `grant` of memory and window, handed
// `lender`.
fn lent_run(
    archive: &[u8],
    grant: u64,
    lender: Option<&Arc<crate::lent::testing::TestLender>>,
) -> Vec<Said> {
    let budget = weaver_graph::Budget {
        memory_bytes: Some(grant),
        window_bytes: Some(grant),
        threads: 1,
        ..Default::default()
    };
    let budget = match lender {
        Some(lender) => lender.lending(budget),
        None => budget,
    };
    let mut emits = Vec::new();
    RarEngine::new().start().run(
        Gate::whole(vec![archive.to_vec()]) as Arc<dyn Volumes>,
        &mut |emit| {
            emits.push(emit);
            true
        },
        budget,
    );
    said(&emits)
}

// A run handed a lender borrows the dictionary its grant cannot hold, and
// decodes through it what a run with room for it on the heap decodes,
// although every lent byte held garbage first. It asks for the dictionary
// once, as it opens the member, and gives it back.
#[test]
fn a_rar5_dictionary_over_the_grant_is_lent_and_given_back() {
    use crate::lent::testing::TestLender;
    let lender = TestLender::new();
    let said = lent_run(LZ, 64 << 10, Some(&lender));
    assert_eq!(said, run(&mut RarEngine::new(), vec![LZ.to_vec()]));
    assert!(said.contains(&Said::Closed(0)), "{said:?}");
    let asked = lender.asked();
    assert_eq!(asked, [256 << 10]);
    assert_eq!(lender.live(), 0);
}

// Without a lender the same grant refuses the dictionary with its sizes, as
// it always did.
#[test]
fn a_rar5_dictionary_over_the_grant_without_a_lender_is_refused() {
    let said = lent_run(LZ, 64 << 10, None);
    assert!(
        said.contains(&Said::Refuse(Why::TooLarge {
            needed: Some(256 << 10),
            allowed: Some(64 << 10),
        })),
        "{said:?}"
    );
    assert!(!said.iter().any(|said| matches!(said, Said::Bytes(..))));
}

// A lender's refusal is the member's verdict: a filesystem's refusal asks
// for the window in RAM, which the owner gives or refuses by its policy;
// any other refusal stands.
#[test]
fn a_rar_window_the_lender_refuses_says_why() {
    use crate::lent::testing::TestLender;
    let full = TestLender::refusing(io::ErrorKind::StorageFull);
    let said = lent_run(LZ, 64 << 10, Some(&full));
    assert!(
        said.contains(&Said::Refuse(Why::TooLarge {
            needed: Some(256 << 10),
            allowed: None,
        })),
        "{said:?}"
    );
    let denied = TestLender::refusing(io::ErrorKind::PermissionDenied);
    let said = lent_run(LZ, 64 << 10, Some(&denied));
    assert!(said.contains(&Said::Refuse(Why::Unsupported)), "{said:?}");
    assert!(!said.iter().any(|said| matches!(said, Said::Bytes(..))));
}

// A RAR 2.9 PPMd model arena over the grant is lent under the same rule as
// its dictionary: a solid run of three members borrows the dictionary and
// one arena, keeps both across the members, decodes what a
// run with room for both on the heap decodes, and gives both back. Without
// a lender the member is refused.
#[test]
fn a_rar3_ppmd_arena_over_the_grant_is_lent_as_a_dictionary_is() {
    use crate::lent::testing::TestLender;
    let grant = 512 << 10;
    let lender = TestLender::new();
    let said = lent_run(PPMD, grant, Some(&lender));
    assert_eq!(said, run(&mut RarEngine::new(), vec![PPMD.to_vec()]));
    assert!(said.contains(&Said::Closed(2)), "{said:?}");
    // The 1 MiB dictionary its headers declare, then the arena its block
    // header declares, `(mem + 1) << 20` bytes.
    assert_eq!(lender.asked(), [MIB as usize, MIB as usize]);
    assert_eq!(lender.live(), 0);

    let said = lent_run(PPMD, grant, None);
    assert!(
        said.iter()
            .any(|said| matches!(said, Said::Refuse(Why::TooLarge { .. }))),
        "{said:?}"
    );
    assert!(!said.iter().any(|said| matches!(said, Said::Bytes(..))));

    // With room for both on the heap nothing is lent.
    let room = TestLender::new();
    let said = lent_run(PPMD, MIB, Some(&room));
    assert_eq!(said, run(&mut RarEngine::new(), vec![PPMD.to_vec()]));
    assert_eq!(room.asked(), Vec::<usize>::new());
}

// A RAR 2.9 member decoding beside others counts its bytes and its
// dictionary, nothing for a PPMd arena it may never use: it fits a grant
// of exactly those, lent or not.
#[test]
fn a_rar3_member_beside_others_counts_its_bytes_and_dictionary() {
    use crate::lent::testing::TestLender;
    let parsed =
        unrar_rs::RarArchive::open_prefix(io::Cursor::new(PPMD.to_vec()), None, NonZeroUsize::MAX)
            .unwrap();
    let info = parsed.member_info(0).unwrap();
    let bytes = info.unpacked_size.unwrap() + info.compression.dict_size;
    let volumes = Gate::whole(vec![PPMD.to_vec()]) as Arc<dyn Volumes>;
    let granted = |memory: u64| weaver_graph::Budget {
        memory_bytes: Some(memory),
        window_bytes: Some(memory),
        threads: 1,
        ..Default::default()
    };
    let alone = |budget: &weaver_graph::Budget| run::may_start_alone(&parsed, &volumes, budget, 0);
    assert_eq!(alone(&granted(bytes)), Some(bytes));
    assert_eq!(alone(&granted(bytes - 1)), None);
    assert_eq!(
        alone(&TestLender::new().lending(granted(bytes))),
        Some(bytes)
    );
}

// A dictionary over the lender's ceiling is not asked for: the decoder
// refuses it with its size against the ceiling.
#[test]
fn a_rar_dictionary_over_the_lenders_ceiling_is_refused_unasked() {
    use crate::lent::testing::TestLender;
    let low = TestLender::up_to(128 << 10);
    let said = lent_run(LZ, 64 << 10, Some(&low));
    assert!(
        said.contains(&Said::Refuse(Why::TooLarge {
            needed: Some(256 << 10),
            allowed: Some(128 << 10),
        })),
        "{said:?}"
    );
    assert_eq!(low.asked(), Vec::<usize>::new());
}

// A lender that lends the RAR 2.9 dictionary and refuses the PPMd arena
// after it: the arena's refusal is the member's verdict, with the arena's
// size, the dictionary it lent is given back, and nothing is said of the
// member's bytes that the arena never decoded.
#[test]
fn a_rar3_ppmd_arena_the_lender_refuses_says_why_with_its_size() {
    use crate::lent::testing::TestLender;
    let full = TestLender::refusing_after(1, io::ErrorKind::StorageFull);
    let said = lent_run(PPMD, 512 << 10, Some(&full));
    assert_eq!(full.asked(), [MIB as usize, MIB as usize]);
    assert!(
        said.contains(&Said::Refuse(Why::TooLarge {
            needed: Some(MIB),
            allowed: None,
        })),
        "{said:?}"
    );
    assert!(!said.iter().any(|said| matches!(said, Said::Bytes(..))));
    assert_eq!(full.live(), 0);

    let denied = TestLender::refusing_after(1, io::ErrorKind::PermissionDenied);
    let said = lent_run(PPMD, 512 << 10, Some(&denied));
    assert_eq!(denied.asked().len(), 2);
    assert!(said.contains(&Said::Refuse(Why::Unsupported)), "{said:?}");
    assert_eq!(denied.live(), 0);
}

// A lone archive is no volume, so its front places nothing, but its headers
// still state the window its decode holds: its member's unpacked size where
// that is under the dictionary, the whole dictionary when it is solid. The
// owner books that window for the run.
#[test]
fn a_lone_archive_states_its_window() {
    let fixture = |path: &str| {
        std::fs::read(format!(
            "{}/../../server/crates/weaver-server-core/tests/fixtures/extraction_profiles/{path}",
            env!("CARGO_MANIFEST_DIR")
        ))
        .unwrap()
    };
    for (path, window) in [
        ("rar5_lz.rar", 226_943),
        ("rar4_solid_ppmd_plain.rar", 1 << 20),
    ] {
        let bytes = fixture(path);
        assert!(<Rar as Format>::front(&bytes).is_none(), "{path}");
        assert_eq!(<Rar as Format>::window(&bytes), Some(window), "{path}");
    }
}
